<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>课程平台</h1><p>在线学习课程内容，学习进度按资源分别记录。</p></div><el-button icon="el-icon-monitor" @click="$router.push('/training-environment')">打开实训环境</el-button></header><div class="course-filters"><el-input v-model="keyword" clearable prefix-icon="el-icon-search" placeholder="按名称搜索" /><el-select v-model="type" clearable placeholder="课程类型"><el-option v-for="item in types" :key="item" :label="item" :value="item" /></el-select><el-select v-model="status" placeholder="学习状态"><el-option label="全部课程" value="all" /><el-option label="学习中" value="learning" /><el-option label="已完成" value="done" /></el-select></div><div class="course-grid"><article v-for="item in filtered" :key="item.course.courseId" class="course-item"><div class="course-item-head"><div><h2>{{ item.course.name }}</h2><span>{{ item.course.courseType }}</span></div></div><p>{{ item.course.description || '暂无课程简介' }}</p><div class="resource-list"><button v-for="resource in item.resources" :key="resource.resourceId" type="button" @click="openResource(resource)"><i :class="icon(resource.resourceType)" /><span>{{ resource.name }}</span><small>{{ resource.resourceType }}</small></button></div></article><div v-if="!filtered.length" class="module-empty"><div class="module-empty-inner"><i class="el-icon-reading" /><strong>暂无可用课程</strong><p>管理员发布课程后将在此显示。</p></div></div></div><el-dialog :title="activeResource ? activeResource.name : '资源预览'" :visible.sync="preview" width="680px"><div v-if="activeResource" class="resource-preview"><i :class="icon(activeResource.resourceType)" /><h2>{{ activeResource.resourceType }} 在线学习</h2><p>此资源仅支持在线预览或发送到实训环境，不支持下载到电脑。</p><el-progress :percentage="progress" /><el-button type="primary" @click="finishResource">标记本资源完成</el-button></div></el-dialog></section></template>
<script>
import { listUserCourses, recordCourseProgress } from '@/api/Courses'
export default { data: () => ({ courses: [], keyword: '', type: '', status: 'all', preview: false, activeResource: null, progress: 0 }), computed: { types () { return [...new Set(this.courses.map(item => item.course.courseType))] }, filtered () { return this.courses.filter(item => (!this.keyword || item.course.name.includes(this.keyword)) && (!this.type || item.course.courseType === this.type)) } }, async created () { const r = await listUserCourses(); this.courses = r.data || [] }, methods: { icon (type) { return ({ EBOOK: 'el-icon-document', VIDEO: 'el-icon-video-play', PPT: 'el-icon-data-board', ARCHIVE: 'el-icon-folder' })[type] || 'el-icon-document' }, openResource (resource) { this.activeResource = resource; this.progress = 0; this.preview = true }, async finishResource () { await recordCourseProgress({ resourceId: this.activeResource.resourceId, progressKind: this.activeResource.resourceType === 'VIDEO' ? 'TIME' : (this.activeResource.resourceType === 'PPT' ? 'SLIDE' : 'PAGE'), progressValue: 100, completed: true }); this.progress = 100; this.$message.success('学习进度已记录') } } }
</script>
